    'activation_nudge_subject_no_event' => 'Put your first event on your ":schedule" schedule',
    'activation_nudge_heading_no_event' => 'Your page is waiting for a date',
    'activation_nudge_body_no_event' => 'Your ":schedule" schedule is set up and its public page is live, but there is nothing on it yet. Add one event and the page starts working: a shareable link, a QR code, and a calendar your audience can subscribe to. An event that repeats weekly or monthly only has to be entered once.',
    'activation_nudge_cta_no_event' => 'Add an event',
    'activation_nudge_import_no_event' => 'Have a flyer or a list of dates? Drop it into AI Import and the event details are filled in for you.',
    'activation_nudge_import_cta_no_event' => 'Try AI Import',

    'activation_nudge_subject_no_ticket_type' => 'Selling tickets for your ":schedule" schedule?',
    'activation_nudge_heading_no_ticket_type' => 'You can sell from this page',
    'activation_nudge_body_no_ticket_type' => 'Your ":schedule" schedule has events published but no ticket types, so the page can be read but not bought from. Adding one takes a name, a price and a quantity. You scan the QR code on every ticket at the door, and Event Schedule takes no platform fee on any plan.',
    'activation_nudge_cta_no_ticket_type' => 'Set up tickets',
    'activation_nudge_subject_no_ticket_type_free' => 'Let people sign up on your ":schedule" schedule',
    'activation_nudge_heading_no_ticket_type_free' => 'Take sign-ups from this page',
    'activation_nudge_body_no_ticket_type_free' => 'Your ":schedule" schedule has events published but no way to sign up for them. Free registration and free tickets are unlimited on your plan, with a QR code for every guest to scan at the door. If you want to charge, you can try selling paid tickets free for 7 days, with no card.',
    'activation_nudge_body_no_ticket_type_free_no_trial' => 'Your ":schedule" schedule has events published but no way to sign up for them. Free registration and free tickets are unlimited on your plan, with a QR code for every guest to scan at the door.',
    'activation_nudge_cta_no_ticket_type_free' => 'Set up registration',

    'activation_nudge_subject_no_gateway' => 'One step left before your ":schedule" schedule can take payment',
    'activation_nudge_heading_no_gateway' => 'Connect a way to get paid',
    'activation_nudge_body_no_gateway' => 'Your ":schedule" schedule has paid tickets set up, but no payment method is connected yet, so buyers cannot pay online. Connecting Stripe takes a couple of minutes and the money goes straight to your own account. You can also take cash at the door instead and keep the tickets exactly as they are.',
    'activation_nudge_cta_no_gateway' => 'Connect payments',

    'activation_nudge_subject_first_sale' => 'You sold your first ticket',
    'activation_nudge_heading_first_sale' => 'First one sold',
    'activation_nudge_body_first_sale' => 'The first ticket on your ":schedule" schedule has been paid for. The buyer has their QR code, and you can scan it at the door from the Sales page. That page also shows who is coming, what they bought and what you have taken so far.',
    'activation_nudge_cta_first_sale' => 'See your sales',

    'activation_nudge_subject_idle_30' => 'Nothing coming up on your ":schedule" schedule',
